import hashlib,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
FAMILIES={};CATEGORY={};SPECIAL={};CONTEXT={}
def pairs(*rows):
 return [dict(ar=a,en=b) for a,b in rows]
def group(key,categories,*rows):
 FAMILIES[key]=pairs(*rows)
 for name in categories.split('|'):CATEGORY[name]=key
def special(words,*rows):
 for name in words.split('|'):SPECIAL[name]=pairs(*rows)
def context(category,word,*rows):CONTEXT[category+'\u0001'+word]=pairs(*rows)

