special('حنفية',('أَفْتَحُ الْحَنَفِيَّةَ لِأَسْتَخْدِمَ الْمَاءَ.','I turn on the tap to use water.'),('أُغْلِقُهَا بَعْدَ الِانْتِهَاءِ.','I turn it off when I finish.'))
special('مشط|فرشاة شعر',('أُرَتِّبُ شَعْرِي بِالْمِشْطِ.','I tidy my hair with a comb.'))
special('شامبو',('نَسْتَخْدِمُ الشَّامْبُو لِغَسْلِ الشَّعْرِ.','We use shampoo to wash hair.'))
special('مناديل',('أَسْتَخْدِمُ مَنْدِيلًا نَظِيفًا لِمَسْحِ أَنْفِي.','I use a clean tissue to wipe my nose.'))
special('مرحاض',('أَسْتَخْدِمُ الْمِرْحَاضَ ثُمَّ أَغْسِلُ يَدَيَّ.','I use the toilet, then wash my hands.'))
special('دش',('أَسْتَحِمُّ لِأُحَافِظَ عَلَى نَظَافَةِ جِسْمِي.','I take a shower to keep my body clean.'))
special('سلة مهملات',('أَضَعُ الْقُمَامَةَ فِي سَلَّةِ الْمُهْمَلَاتِ.','I put rubbish in the bin.'))
special('مكنسة|مكنسة كهربائية|ممسحة',('نَسْتَخْدِمُ أَدَوَاتِ التَّنْظِيفِ لِإِزَالَةِ الْأَوْسَاخِ عَنِ الْأَرْضِ.','We use cleaning tools to remove dirt from the floor.'))
special('ثلاجة|مجمد',('تُحَافِظُ الثَّلَّاجَةُ عَلَى الطَّعَامِ بَارِدًا.','A fridge keeps food cold.'),('أُغْلِقُ بَابَهَا بَعْدَ أَخْذِ مَا أَحْتَاجُهُ.','I close its door after taking what I need.'))
special('موقد|فرن|ميكروويف|غلاية',('يَسْتَخْدِمُ الْكِبَارُ هَذَا الْجِهَازَ لِتَسْخِينِ الطَّعَامِ أَوِ الْمَاءِ.','Grown-ups use this device to heat food or water.'),('أَبْتَعِدُ عَنِ الْأَشْيَاءِ السَّاخِنَةِ.','I keep away from hot things.'))
special('سكين|مقشرة|مبشرة|لوح تقطيع',('يُقَطِّعُ الشَّخْصُ الْكَبِيرُ الطَّعَامَ بِأَدَوَاتٍ مُنَاسِبَةٍ.','A grown-up cuts food using suitable tools.'))
special('مقص',('نَسْتَخْدِمُ مِقَصًّا مُنَاسِبًا لِقَصِّ الْوَرَقِ.','We use suitable scissors to cut paper.'),('أَطْلُبُ الْمُسَاعَدَةَ إِذَا احْتَجْتُهَا.','I ask for help when I need it.'))
special('ممحاة',('أَسْتَخْدِمُ الْمِمْحَاةَ لِمَسْحِ أَثَرِ قَلَمِ الرَّصَاصِ.','I use an eraser to remove pencil marks.'))
special('مسطرة|شريط قياس',('أَسْتَخْدِمُ أَدَاةَ الْقِيَاسِ لِمَعْرِفَةِ الطُّولِ.','I use a measuring tool to find the length.'))
special('غراء',('أَسْتَخْدِمُ الْغِرَاءَ لِإِلْصَاقِ قِطَعِ الْوَرَقِ.','I use glue to stick pieces of paper together.'))
special('دفتر',('أَكْتُبُ وَأَرْسُمُ فِي دَفْتَرِي.','I write and draw in my notebook.'))
special('حقيبة|حقيبة ظهر|حقيبة سفر|مقلمة',('أَضَعُ أَدَوَاتِي فِي حَقِيبَتِي لِأَحْمِلَهَا بِسُهُولَةٍ.','I put my things in a bag to carry them easily.'))
special('هاتف',('أَسْتَخْدِمُ الْهَاتِفَ مَعَ شَخْصٍ كَبِيرٍ لِلتَّوَاصُلِ.','I use a phone with a grown-up to communicate.'))
special('كاميرا',('أَسْتَخْدِمُ الْكَامِيرَا لِالْتِقَاطِ صُورَةٍ.','I use a camera to take a picture.'),('أَسْتَأْذِنُ قَبْلَ تَصْوِيرِ الْآخَرِينَ.','I ask permission before taking pictures of other people.'))
special('حاسوب|حاسوب محمول|جهاز لوحي',('أَسْتَخْدِمُ الْجِهَازَ لِلْكِتَابَةِ وَالتَّعَلُّمِ مَعَ الْمُرَبِّي.','I use the device to write and learn with my grown-up.'))
special('لوحة مفاتيح',('أَضْغَطُ أَزْرَارَ لَوْحَةِ الْمَفَاتِيحِ لِأَكْتُبَ.','I press keys on the keyboard to type.'))
special('طابعة',('تَطْبَعُ الطَّابِعَةُ الْكَلِمَاتِ وَالصُّوَرَ عَلَى الْوَرَقِ.','A printer prints words and pictures on paper.'))
special('سماعة|مكبر صوت',('تُسَاعِدُنِي السَّمَّاعَةُ عَلَى سَمَاعِ الصَّوْتِ.','A speaker helps me hear sound.'),('أَخْتَارُ صَوْتًا هَادِئًا لِأُحَافِظَ عَلَى أُذُنَيَّ.','I choose a quiet volume to care for my ears.'))
special('سيارة|حافلة|حافلة مدرسية|سيارة أجرة',('تَنْقُلُنِي الْمَرْكَبَةُ إِلَى الْمَكَانِ الَّذِي أُرِيدُهُ.','A vehicle takes me to the place I want to go.'),('أَجْلِسُ فِي الْمَقْعَدِ الْمُنَاسِبِ وَأَتَبِعُ إِرْشَادَاتِ الْأَمَانِ.','I sit in a suitable seat and follow safety guidance.'))
special('دراجة',('أُحَرِّكُ الدَّوَّاسَتَيْنِ لِتَسِيرَ الدَّرَّاجَةُ.','I turn the pedals to move the bicycle.'),('أَلْبَسُ خُوذَةً وَأَرْكَبُ فِي مَكَانٍ آمِنٍ.','I wear a helmet and ride in a safe place.'))
special('خوذة|حزام أمان',('تُسَاعِدُنِي أَدَوَاتُ الْحِمَايَةِ عَلَى تَقْلِيلِ الْإِصَابَةِ.','Protective equipment helps reduce injury.'))
special('سيارة إسعاف|مسعف|إسعاف',('تُسَاعِدُ سَيَّارَةُ الْإِسْعَافِ عَلَى نَقْلِ مَنْ يَحْتَاجُ إِلَى الْعِلَاجِ.','An ambulance helps transport someone who needs treatment.'))
special('سيارة إطفاء|رجل إطفاء|محطة إطفاء',('يُسَاعِدُ رِجَالُ الْإِطْفَاءِ عَلَى إِخْمَادِ الْحَرَائِقِ وَإِنْقَاذِ النَّاسِ.','Firefighters help put out fires and rescue people.'))
special('سيارة شرطة|شرطي|مركز شرطة',('يُسَاعِدُ الشُّرْطِيُّ عَلَى حِفْظِ الْأَمَانِ وَتَنْظِيمِ الْمُرُورِ.','A police officer helps keep people safe and manage traffic.'))
special('رافعة|جرافة|حفارة|محراث|جرار',('يَسْتَخْدِمُ الْكِبَارُ هَذِهِ الْآلَةَ فِي أَعْمَالِ الْبِنَاءِ أَوِ الزِّرَاعَةِ.','Grown-ups use this machine for building or farming.'))
special('طائرة|طائرة ركاب|مروحية',('تَنْقُلُ الطَّائِرَةُ النَّاسَ فِي الْجَوِّ.','An aircraft carries people through the air.'))
special('قطار|مترو|ترام|قطار سريع|قاطرة',('يَسِيرُ الْقِطَارُ عَلَى السِّكَّةِ لِنَقْلِ النَّاسِ أَوِ الْبَضَائِعِ.','A train travels on tracks to carry people or goods.'))
special('شاحنة|شاحنة نقل|سفينة شحن|طائرة شحن',('تَنْقُلُ هَذِهِ الْوَسِيلَةُ الْبَضَائِعَ مِنْ مَكَانٍ إِلَى آخَرَ.','This vehicle carries goods from one place to another.'))
special('شاحنة قمامة',('تَجْمَعُ شَاحِنَةُ الْقُمَامَةِ الْمُهْمَلَاتِ لِيَبْقَى الْمَكَانُ نَظِيفًا.','A rubbish truck collects waste to keep the place clean.'))
special('طبيب|ممرض|عيادة|مستشفى',('يُسَاعِدُنِي الطَّبِيبُ وَالْمُمَرِّضُ عِنْدَمَا أَحْتَاجُ إِلَى الْعِنَايَةِ.','A doctor and a nurse help me when I need care.'))
special('طبيب أسنان',('يَفْحَصُ طَبِيبُ الْأَسْنَانِ أَسْنَانِي وَيُسَاعِدُنِي عَلَى الْعِنَايَةِ بِهَا.','A dentist checks my teeth and helps me care for them.'))
special('معلم|مدرسة|فصل',('يُسَاعِدُنِي الْمُعَلِّمُ عَلَى الْقِرَاءَةِ وَالتَّعَلُّمِ.','A teacher helps me read and learn.'))
special('نجار',('يَسْتَخْدِمُ النَّجَّارُ الْخَشَبَ لِصُنْعِ الْأَثَاثِ.','A carpenter uses wood to make furniture.'))
special('خباز|مخبز',('يَصْنَعُ الْخَبَّازُ الْخُبْزَ وَيَخْبِزُهُ فِي الْفُرْنِ.','A baker makes bread and bakes it in an oven.'))
special('مزارع|مزرعة',('يَزْرَعُ الْمُزَارِعُ الْمَحَاصِيلَ وَيَعْتَنِي بِهَا.','A farmer grows crops and cares for them.'))
special('خياط',('يَسْتَخْدِمُ الْخَيَّاطُ الْقُمَاشَ وَالْخَيْطَ لِصُنْعِ الْمَلَابِسِ.','A tailor uses fabric and thread to make clothes.'))
special('صيدلي',('يُسَاعِدُ الصَّيْدَلِيُّ الْكِبَارَ عَلَى اسْتِخْدَامِ الدَّوَاءِ بِشَكْلٍ صَحِيحٍ.','A pharmacist helps grown-ups use medicine correctly.'))
special('دواء|حقنة',('لَا أَسْتَخْدِمُ الدَّوَاءَ إِلَّا مَعَ شَخْصٍ كَبِيرٍ وَبِتَوْجِيهٍ صَحِيحٍ.','I only use medicine with a grown-up and proper guidance.'))
special('ضمادة',('تُغَطِّي الضِّمَادَةُ الْجُرْحَ لِتُسَاعِدَ عَلَى حِمَايَتِهِ.','A bandage covers a wound to help protect it.'))
special('ميزان حرارة|ترمومتر',('نَسْتَخْدِمُ مِيزَانَ الْحَرَارَةِ لِقِيَاسِ دَرَجَةِ الْحَرَارَةِ.','We use a thermometer to measure temperature.'))
special('رأس|دماغ',('يُسَاعِدُنِي الدِّمَاغُ عَلَى التَّفْكِيرِ وَالتَّعَلُّمِ.','My brain helps me think and learn.'))
special('عين|نظر',('أَسْتَخْدِمُ عَيْنَيَّ لِرُؤْيَةِ الْأَشْيَاءِ.','I use my eyes to see things.'))
special('أذن|سمع',('أَسْتَخْدِمُ أُذُنَيَّ لِسَمَاعِ الْأَصْوَاتِ.','I use my ears to hear sounds.'))
special('أنف|شم',('أَسْتَخْدِمُ أَنْفِي لِشَمِّ الرَّوَائِحِ.','I use my nose to smell things.'))
special('لسان|تذوق',('أَسْتَخْدِمُ لِسَانِي لِتَذَوُّقِ الطَّعَامِ.','I use my tongue to taste food.'))
special('أسنان',('أَمْضَغُ الطَّعَامَ بِأَسْنَانِي.','I chew food with my teeth.'))
special('يد|كف|أصابع|إصبع|إبهام',('أَسْتَخْدِمُ يَدَيَّ لِحَمْلِ الْأَشْيَاءِ وَالْعَمَلِ.','I use my hands to carry things and work.'))
special('قدم|ساق|ركبة|كعب|كاحل|باطن القدم',('تُسَاعِدُنِي سَاقَايَ وَقَدَمَايَ عَلَى الْمَشْيِ وَالْحَرَكَةِ.','My legs and feet help me walk and move.'))
special('رئة',('تُسَاعِدُنِي الرِّئَتَانِ عَلَى التَّنَفُّسِ.','My lungs help me breathe.'))
special('معدة',('تُسَاعِدُ الْمَعِدَةُ عَلَى هَضْمِ الطَّعَامِ.','The stomach helps digest food.'))
special('جلد',('يُغَطِّي الْجِلْدُ جِسْمِي وَيُسَاعِدُ عَلَى حِمَايَتِهِ.','Skin covers my body and helps protect it.'))
special('عظم|جمجمة',('تُسَاعِدُ الْعِظَامُ عَلَى دَعْمِ الْجِسْمِ وَحِمَايَتِهِ.','Bones help support and protect the body.'))
special('عضلة',('تُسَاعِدُنِي الْعَضَلَاتُ عَلَى الْحَرَكَةِ.','My muscles help me move.'))
special('قطة',('تَمْشِي الْقِطَّةُ عَلَى أَرْبَعِ قَوَائِمَ.','A cat walks on four legs.'),('أُرَاقِبُهَا بِهُدُوءٍ وَأَتْرُكُ لَهَا مَسَاحَةً.','I watch it quietly and give it space.'))
special('كلب',('يَسْتَخْدِمُ الْكَلْبُ أَنْفَهُ لِشَمِّ الرَّوَائِحِ.','A dog uses its nose to smell things.'))
special('بقرة',('تَأْكُلُ الْبَقَرَةُ الْعُشْبَ، وَنَحْصُلُ مِنْهَا عَلَى الْحَلِيبِ.','A cow eats grass, and we get milk from it.'))
special('نحلة',('تَنْتَقِلُ النَّحْلَةُ بَيْنَ الْأَزْهَارِ وَتُسَاعِدُ عَلَى التَّلْقِيحِ.','A bee moves between flowers and helps pollination.'),('أُرَاقِبُهَا دُونَ أَنْ أَلْمَسَهَا.','I watch it without touching it.'))
special('دجاجة',('تَضَعُ الدَّجَاجَةُ الْبَيْضَ.','A hen lays eggs.'))
special('زرافة',('تُسَاعِدُ رَقَبَةُ الزَّرَافَةِ الطَّوِيلَةُ عَلَى الْوُصُولِ إِلَى الْأَوْرَاقِ.','A giraffe’s long neck helps it reach leaves.'))
special('جذر',('يَمْتَصُّ الْجَذْرُ الْمَاءَ مِنَ التُّرْبَةِ.','A root takes in water from the soil.'))
special('بذرة|بذور',('يُمْكِنُ أَنْ تَنْمُوَ الْبَذْرَةُ فَتُصْبِحَ نَبَاتًا.','A seed can grow into a plant.'))
special('شجرة',('تَمْنَحُ الشَّجَرَةُ الظِّلَّ، وَتُوَفِّرُ مَكَانًا لِبَعْضِ الْحَيَوَانَاتِ.','A tree gives shade and provides a home for some animals.'))
special('شمس',('تَمْنَحُنَا الشَّمْسُ الضَّوْءَ وَالدِّفْءَ.','The sun gives us light and warmth.'),('لَا أَنْظُرُ مُبَاشَرَةً إِلَى الشَّمْسِ.','I do not look directly at the sun.'))
special('قمر',('نَرَى الْقَمَرَ لِأَنَّهُ يَعْكِسُ ضَوْءَ الشَّمْسِ.','We see the moon because it reflects sunlight.'))
special('مطر',('يُسَاعِدُ الْمَطَرُ عَلَى سَقْيِ النَّبَاتَاتِ.','Rain helps water plants.'))
special('رصيف',('أَمْشِي عَلَى الرَّصِيفِ بَعِيدًا عَنْ مَسَارِ السَّيَّارَاتِ.','I walk on the pavement away from moving cars.'))
special('ممر مشاة|عبور',('أَعْبُرُ الشَّارِعَ مِنَ الْمَكَانِ الْمُنَاسِبِ مَعَ شَخْصٍ كَبِيرٍ.','I cross the road at a suitable place with a grown-up.'))
special('إشارة مرور',('تُنَظِّمُ إِشَارَةُ الْمُرُورِ حَرَكَةَ السَّيَّارَاتِ وَالْمُشَاةِ.','A traffic light organizes cars and people crossing.'))
special('مغناطيس',('يَجْذِبُ الْمِغْنَاطِيسُ بَعْضَ الْمَعَادِنِ، وَلَا يَجْذِبُ كُلَّ شَيْءٍ.','A magnet attracts some metals, but not everything.'))
special('مجهر',('يُسَاعِدُنَا الْمِجْهَرُ عَلَى رُؤْيَةِ أَشْيَاءَ صَغِيرَةٍ جِدًّا.','A microscope helps us see very tiny things.'))
special('تلسكوب',('يُسَاعِدُنَا التِّلِسْكُوبُ عَلَى رُؤْيَةِ أَجْسَامٍ بَعِيدَةٍ.','A telescope helps us see distant objects.'))
special('ميزان',('نَسْتَخْدِمُ الْمِيزَانَ لِقِيَاسِ الْكَتْلَةِ.','We use a scale to measure mass.'))
special('خريطة|كرة أرضية',('تُسَاعِدُنَا الْخَرِيطَةُ عَلَى مَعْرِفَةِ الْأَمَاكِنِ.','A map helps us learn where places are.'))
